/*
 * High-performance portfolio calculations using C extension
 *
 * Implements the same arithmetic as portfolio_baseline.py, but in C:
 *   risk   = sqrt(x^T S x)   (S is the covariance matrix)
 *   return = x^T r
 *
 * Inputs may be NumPy arrays (zero-copy fast path) or ordinary Python
 * sequences such as lists of lists.  Reading Python sequences directly in C
 * avoids the expensive list -> ndarray conversion for large covariance
 * matrices, while preserving exactly the baseline's accumulation order.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

/* Convert one Python object to a double, allowing ints/other numerics. */
static int object_to_double(PyObject *obj, double *value)
{
    if (PyFloat_Check(obj)) {
        *value = PyFloat_AS_DOUBLE(obj);
        return 0;
    }

    PyObject *as_float = PyNumber_Float(obj);
    if (as_float == NULL)
        return -1;
    *value = PyFloat_AS_DOUBLE(as_float);
    Py_DECREF(as_float);
    return 0;
}

/*
 * Load a 1D vector into a freshly allocated double array.
 * On success returns 0 and sets *n_out and *data_out (caller frees data).
 * On failure returns -1 with a Python exception set.
 */
static int load_vector(PyObject *obj, npy_intp *n_out, double **data_out)
{
    npy_intp n;
    double *data = NULL;

    if (PyArray_Check(obj)) {
        PyArrayObject *array = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (array == NULL)
            return -1;
        if (PyArray_NDIM(array) != 1) {
            PyErr_SetString(PyExc_ValueError, "expected a 1D array");
            Py_DECREF(array);
            return -1;
        }
        n = PyArray_DIM(array, 0);
        data = (double *)malloc((size_t)n * sizeof(double));
        if (data == NULL && n > 0) {
            PyErr_NoMemory();
            Py_DECREF(array);
            return -1;
        }
        if (n > 0)
            memcpy(data, PyArray_DATA(array), (size_t)n * sizeof(double));
        Py_DECREF(array);
    } else {
        PyObject *fast = PySequence_Fast(obj, "expected a sequence");
        if (fast == NULL)
            return -1;

        n = PySequence_Fast_GET_SIZE(fast);
        data = (double *)malloc((size_t)n * sizeof(double));
        if (data == NULL && n > 0) {
            PyErr_NoMemory();
            Py_DECREF(fast);
            return -1;
        }

        PyObject **items = PySequence_Fast_ITEMS(fast);
        for (npy_intp i = 0; i < n; ++i) {
            if (object_to_double(items[i], &data[i]) < 0) {
                free(data);
                Py_DECREF(fast);
                return -1;
            }
        }
        Py_DECREF(fast);
    }

    *n_out = n;
    *data_out = data;
    return 0;
}

/*
 * A view of the covariance matrix.  Either a contiguous float64 ndarray
 * (array != NULL) or a Python sequence of list/tuple rows (fast != NULL).
 */
typedef struct {
    npy_intp n;
    PyArrayObject *array;
    PyObject *fast;
    PyObject **rows;
} CovView;

static void cov_view_clear(CovView *view)
{
    Py_XDECREF(view->array);
    Py_XDECREF(view->fast);
    view->array = NULL;
    view->fast = NULL;
    view->rows = NULL;
}

/*
 * Load a 2D covariance matrix.  NumPy arrays are used without copying.
 * A plain outer sequence is used directly when all rows are lists/tuples;
 * otherwise it is converted to a float64 ndarray as a fallback.
 */
static int load_covariance(PyObject *obj, npy_intp n, CovView *view)
{
    memset(view, 0, sizeof(*view));
    view->n = n;

    if (!PyArray_Check(obj)) {
        PyObject *fast = PySequence_Fast(obj, "expected a covariance matrix");
        if (fast == NULL)
            return -1;

        npy_intp outer_n = PySequence_Fast_GET_SIZE(fast);
        PyObject **rows = PySequence_Fast_ITEMS(fast);

        if (outer_n != n) {
            PyErr_SetString(PyExc_ValueError,
                            "covariance matrix must be n x n where n is len(weights)");
            Py_DECREF(fast);
            return -1;
        }

        int direct = 1;
        for (npy_intp i = 0; i < n; ++i) {
            PyObject *row = rows[i];
            if (!(PyList_Check(row) || PyTuple_Check(row))) {
                direct = 0;
                break;
            }
            if (PySequence_Fast_GET_SIZE(row) != n) {
                PyErr_SetString(PyExc_ValueError,
                                "covariance matrix must be n x n where n is len(weights)");
                Py_DECREF(fast);
                return -1;
            }
        }

        if (direct) {
            view->fast = fast;
            view->rows = rows;
            return 0;
        }
        Py_DECREF(fast);
    }

    view->array = (PyArrayObject *)PyArray_FROM_OTF(
        obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (view->array == NULL)
        return -1;

    if (PyArray_NDIM(view->array) != 2 ||
        PyArray_DIM(view->array, 0) != n ||
        PyArray_DIM(view->array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "covariance matrix must be n x n where n is len(weights)");
        cov_view_clear(view);
        return -1;
    }
    return 0;
}

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *cov_obj;
    PyObject *result = NULL;
    npy_intp n = 0;
    double *x = NULL;
    CovView cov;

    (void)self;
    memset(&cov, 0, sizeof(cov));

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    if (load_vector(weights_obj, &n, &x) < 0)
        return NULL;

    if (load_covariance(cov_obj, n, &cov) < 0) {
        free(x);
        return NULL;
    }

    /*
     * Follow the baseline's accumulation order exactly:
     * first compute temp = S * x, then x^T * temp.
     */
    double risk_squared = 0.0;

    if (cov.array != NULL) {
        const double *restrict S = (const double *)PyArray_DATA(cov.array);

        for (npy_intp i = 0; i < n; ++i) {
            const double *restrict row = S + i * n;
            double row_sum = 0.0;
            for (npy_intp j = 0; j < n; ++j)
                row_sum += row[j] * x[j];
            risk_squared += x[i] * row_sum;
        }
    } else {
        for (npy_intp i = 0; i < n; ++i) {
            PyObject *row = cov.rows[i];
            double row_sum = 0.0;

            if (PyList_Check(row)) {
                for (npy_intp j = 0; j < n; ++j) {
                    double value;
                    if (object_to_double(PyList_GET_ITEM(row, j), &value) < 0)
                        goto error;
                    row_sum += value * x[j];
                }
            } else {
                for (npy_intp j = 0; j < n; ++j) {
                    double value;
                    if (object_to_double(PyTuple_GET_ITEM(row, j), &value) < 0)
                        goto error;
                    row_sum += value * x[j];
                }
            }
            risk_squared += x[i] * row_sum;
        }
    }

    result = PyFloat_FromDouble(sqrt(risk_squared));
    goto done;

error:
    result = NULL;

done:
    cov_view_clear(&cov);
    free(x);
    return result;
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *returns_obj;
    npy_intp n = 0, m = 0;
    double *x = NULL, *r = NULL;

    (void)self;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    if (load_vector(weights_obj, &n, &x) < 0)
        return NULL;

    if (load_vector(returns_obj, &m, &r) < 0) {
        free(x);
        return NULL;
    }

    if (n != m) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected returns must have the same length");
        free(x);
        free(r);
        return NULL;
    }

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += x[i] * r[i];

    free(x);
    free(r);
    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}
